class TestIterNumbers:
    def test_basic(self):
        results = list(iter_numbers("Value is 4,500.00 today"))
        assert len(results) == 1
        raw, start, end, val = results[0]
        assert raw == "4,500.00"
        assert val == Decimal("4500.00")
