        assert len(results) == 1
        raw, start, end, val = results[0]
        assert val == dt.date(2026, 3, 4)
        assert "On 2026-03-04 we met"[start:end] == raw

    def test_multiple(self):
        results = list(iter_dates("2026-03-04 and 4 March 2026"))
